/// <summary>
/// PaffH 07.09.21
/// </summary>
/// <param name = "_lookupCtrl">lookup control</param>
/// <param name = "_currencyCode">optional: filter for currencyCode </param>
/// <param name = "_quotationIdToExclude">optional: QuotationId to exclude </param>
public static void lookupKCS_RefQuotationId(FormStringControl  _lookupCtrl
    , CurrencyCode _currencyCode = ''
    , SalesQuotationId _quotationIdToExclude = '')
{
    SysTableLookup          sysTableLookup;
    Query                   query;
    QueryBuildDataSource    qbds1;

    sysTableLookup      = SysTableLookup::newParameters(tableNum(SalesQuotationTable), _lookupCtrl);
    query               = new Query();
    qbds1        = query.addDataSource(tableNum(SalesQuotationTable));
    if (_quotationIdToExclude)
    {
        qbds1.addRange(fieldNum(SalesQuotationTable, QuotationId)).value(SysQuery::valueNot(_quotationIdToExclude));
    }
    if (_currencyCode)
    {
        qbds1.addRange(fieldNum(SalesQuotationTable, CurrencyCode)).value(queryValue(_currencyCode));
    }

    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, QuotationId), true);
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, QuotationName));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, CustAccount));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable, CustAccount));
    sysTableLookup.addLookupMethod(tableMethodStr(SalesQuotationTable, customerName));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
